node --version
"--- browsers ---"
$paths = @(
  "$env:LOCALAPPDATA\Google\Chrome\User Data",
  "$env:LOCALAPPDATA\Microsoft\Edge\User Data",
  "$env:LOCALAPPDATA\BraveSoftware\Brave-Browser\User Data",
  "$env:APPDATA\Mozilla\Firefox\Profiles"
)
foreach ($p in $paths) {
  if (Test-Path $p) { "FOUND: $p" } else { "missing: $p" }
}","description":"Check node and installed browsers"}

{"command":"$ErrorActionPreference = 'SilentlyContinue'
foreach ($b in @(@{n='Chrome'; p="$env:LOCALAPPDATA\Google\Chrome\User Data"}, @{n='Edge'; p="$env:LOCALAPPDATA\Microsoft\Edge\User Data"})) {
  Get-ChildItem -Path $b.p -Directory | Where-Object { $_.Name -eq 'Default' -or $_.Name -like 'Profile *' } | ForEach-Object {
    $sess = Join-Path $_.FullName 'Sessions'
    if (Test-Path $sess) {
      "=== $($b.n) / $($_.Name) ==="
      Get-ChildItem $sess -File | Sort-Object LastWriteTime -Descending | Select-Object -First 8 Name, Length, LastWriteTime | Format-Table -AutoSize | Out-String -Width 160
    }
  }
}","description":"List Chrome/Edge session files"}

{"path":"C:\Users\spay\AppData\Local\Temp\snss-probe.js","content":"// throwaway probe: check SNSS structure + string encoding in a Chrome session file
const fs = require('fs');
const file = process.argv[2];
const buf = fs.readFileSync(file);
console.log('size', buf.length);
console.log('magic', JSON.stringify(buf.subarray(0, 4).toString('latin1')), 'ver', buf.readInt32LE(4));

let off = 8;
let cmds = 0;
const counts = {};
for (let i = 0; i < 25 && off + 8 <= buf.length; i++) {
  const len = buf.readInt32LE(off);
  const id = buf.readInt32LE(off + 4);
  if (len < 4 || off + 4 + len > buf.length) { console.log('bad len at', off, len); break; }
  const payload = buf.subarray(off + 8, off + 4 + len);
  counts[id] = (counts[id] || 0) + 1;
  // probe payload for http strings in both encodings
  const ascii = payload.toString('latin1');
  const utf16 = payload.toString('utf16le');
  const a = ascii.match(/https?:\/\/[\x20-\x7e]{10,120}/);
  const u = utf16.match(/https?:\/\/[\x20-\x7e]{10,120}/);
  console.log(`cmd#${i} id=${id} len=${len} ascii=${a ? JSON.stringify(a[0].slice(0, 70)) : '-'} utf16=${u ? JSON.stringify(u[0].slice(0, 70)) : '-'}`);
  off += 4 + len;
  cmds++;
}
console.log('scanned cmds', cmds, 'ids', counts);

// global scan of the whole file for utf16 http strings
const whole16 = buf.toString('utf16le');
const urls16 = whole16.match(/https?:\/\/[^\s\x00-\x1f]{8,200}/g) || [];
const wholeA = buf.toString('latin1');
const urlsA = wholeA.match(/https?:\/\/[^\x00-\x1f\s]{8,200}/g) || [];
console.log('utf16 urls', urls16.length, urls16.slice(0, 5));
console.log('latin urls', urlsA.length, urlsA.slice(0, 5));"}
